const rows = $input.all().map(i => i.json);
const keyRow = rows.find(r => String(r.student || '').trim().toLowerCase() === 'answer_key');
if (!keyRow) { throw new Error('CSV needs a row whose student column is answer_key'); }
const qCols = Object.keys(keyRow).filter(k => /^Q\d+$/i.test(k));
const norm = v => String(v ?? '').trim().toUpperCase();
const students = rows.filter(r => r !== keyRow && String(r.student || '').trim() !== '');
const n = Math.max(students.length, 1);
const keyCounts = {};
const roster = students.map((r, idx) => {
  const id = 'Student_' + String(idx + 1).padStart(2, '0');
  let correct = 0;
  const mistakes = [];
  for (const q of qCols) {
    const a = norm(r[q]);
    if (a === norm(keyRow[q])) { correct++; }
    else { const k = q + ':' + (a || 'blank'); mistakes.push(k); keyCounts[k] = (keyCounts[k] || 0) + 1; }
  }
  return { id, name: String(r.student).trim(), percent: Math.round(100 * correct / Math.max(qCols.length, 1)), mistakes };
});
const CLASS_WIDE = 0.3;
const groups = Object.entries(keyCounts).map(e => {
  const k = e[0], c = e[1];
  const scope = c / n >= CLASS_WIDE ? 'class-wide' : (c >= 2 ? 'small-group' : 'individual');
  return { key: k, question: k.split(':')[0], wrong_choice: k.split(':')[1], correct_choice: norm(keyRow[k.split(':')[0]]), students: c, percent: Math.round(100 * c / n), scope };
}).sort((a, b) => b.students - a.students);
const scopeOf = {};
groups.forEach(g => { scopeOf[g.key] = g.scope; });
const individualQs = [...new Set(groups.filter(g => g.scope === 'individual').map(g => g.question))];
const questions = qCols.map(q => {
  const key = norm(keyRow[q]);
  const right = students.filter(r => norm(r[q]) === key).length;
  return { question: q, correct_answer: key, percent_correct: Math.round(100 * right / n) };
}).sort((a, b) => a.percent_correct - b.percent_correct);
const form = $('Teacher Upload Form').first().json;
return [{ json: {
  course: form['Course topic'] || 'the course',
  teacherEmail: form['Teacher email'] || '',
  questionText: form['Quiz questions'] || '',
  studentCount: students.length,
  classAverage: Math.round(roster.reduce((s, x) => s + x.percent, 0) / n),
  questions,
  misconceptionGroups: groups.filter(g => g.scope !== 'individual'),
  individualErrorQuestions: individualQs,
  individualErrorStudents: roster.filter(s => s.mistakes.some(k => scopeOf[k] === 'individual')).length,
  masteredStudents: roster.filter(s => s.mistakes.length === 0).length,
  roster: roster.map(s => ({ id: s.id, name: s.name, percent: s.percent, mistakes: s.mistakes, scopes: s.mistakes.map(k => scopeOf[k]) }))
} }];

