const a = $input.first().json.output || {};
const info = $('Anonymize & Group by Misconception').first().json;
const diag = $('Diagnose Misconceptions').first().json.output || {};
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const quests = Array.isArray(a.side_quests) ? a.side_quests : [];
const stepsText = steps => (steps || []).map((s, i) => {
  let t = (i + 1) + '. ' + (s.story_beat ? '[' + s.story_beat + '] ' : '') + s.prompt + '\n';
  (s.choices || []).forEach(c => { t += '   ' + c.label + ') ' + c.text + (c.is_correct ? '  <- correct' : '') + '\n      feedback: ' + c.feedback + '\n'; });
  return t;
}).join('');
const stepsHtml = steps => '<ol>' + (steps || []).map(s => '<li><p><em>' + esc(s.story_beat) + '</em></p><p>' + esc(s.prompt) + '</p><p>' + (s.choices || []).map(c => esc(c.label + ') ' + c.text)).join('<br>') + '</p></li>').join('') + '</ol>';
const questFor = key => quests.find(q => (q.targets || []).includes(key));
const personal = quests.find(q => (q.targets || []).includes('individual'));
const plan = info.roster.map(s => {
  const items = ['Core Mission'];
  s.mistakes.forEach((k, i) => {
    const sc = s.scopes[i];
    if (sc === 'small-group') { const q = questFor(k); if (q && !items.includes(q.name)) items.push(q.name); }
    if (sc === 'individual' && personal && !items.includes(personal.name)) items.push(personal.name);
  });
  if (s.mistakes.length === 0 && a.challenge_extension) items.push('Challenge Extension');
  return { name: s.name, id: s.id, percent: s.percent, items };
});
let text = 'ReTeach plan for ' + info.course + ' (' + info.studentCount + ' students, avg ' + info.classAverage + '%)\n\n';
text += 'CLASS PATTERN\n' + (diag.class_summary || '') + '\n';
(diag.misconceptions || []).forEach(m => { text += '- [' + m.scope + '] ' + m.concept + ' (' + m.students + ' students): ' + m.likely_misconception + ' | ' + m.evidence + '\n'; });
text += '\nONE ASSIGNMENT, PERSONAL PATHS: ' + (a.title || '') + '\n' + (a.story_intro || '') + '\nWhy: ' + (a.teacher_note || '') + '\n';
if (Array.isArray(a.checks) && a.checks.length) { text += '\nSELF-CHECK FIXES (' + a.checks.length + '):\n' + a.checks.map(c => '- ' + c).join('\n') + '\n'; }
text += '\nWHO GETS WHAT (names never sent to the AI)\n' + plan.map(p => p.name + ' (' + p.percent + '%): ' + p.items.join(' + ')).join('\n') + '\n';
text += '\n=== CORE MISSION (everyone) ===\n' + stepsText((a.core_mission || {}).steps);
quests.forEach(q => { text += '\n=== SIDE QUEST: ' + q.name + ' (' + q.for_whom + ') ===\n' + stepsText(q.steps); });
if (a.challenge_extension) { text += '\n=== CHALLENGE EXTENSION (mastered students) ===\n' + stepsText(a.challenge_extension.steps); }
let html = '<h2>' + esc(a.title) + '</h2><p>' + esc(a.story_intro) + '</p><h3>Core Mission (everyone)</h3>' + stepsHtml((a.core_mission || {}).steps);
quests.forEach(q => { html += '<h3>Side Quest: ' + esc(q.name) + '</h3><p><em>' + esc(q.for_whom) + '</em></p>' + stepsHtml(q.steps); });
if (a.challenge_extension) { html += '<h3>Challenge Extension</h3>' + stepsHtml(a.challenge_extension.steps); }
const stepsStudent = steps => (steps || []).map((s, i) => (i + 1) + '. ' + (s.story_beat ? s.story_beat + ' ' : '') + s.prompt + '\n' + (s.choices || []).map(c => '   ' + c.label + ') ' + c.text).join('\n') + '\n').join('\n');
let studentText = (a.story_intro || '') + '\n\n=== CORE MISSION (everyone) ===\n' + stepsStudent((a.core_mission || {}).steps);
quests.forEach(q => { studentText += '\n=== SIDE QUEST: ' + q.name + ' ===\n' + stepsStudent(q.steps); });
if (a.challenge_extension) { studentText += '\n=== CHALLENGE EXTENSION ===\n' + stepsStudent(a.challenge_extension.steps); }
studentText += '\nEveryone completes the Core Mission. Your teacher will tell you which Side Quest or Challenge is yours.';
return [{ json: { studentText, title: a.title || 'ReTeach assignment', reviewText: text, canvasHtml: html, draftJson: JSON.stringify(a), teacherEmail: info.teacherEmail, plan } }];

